\n\n\n\n\n\n\n\n\n\n\n<\u002Fscript>\n<\u002Fhead>\n\n\n\n\n\nwindow.OM_SCENES = '[{\"name\":\"Boot\",\"dur\":3,\"desc\":\"Grid boots up and the root node glitches into existence, camera zoomed tight.\"},{\"name\":\"Root\",\"dur\":3,\"desc\":\"Root identity resolves: kugguk2022, Zolton Farkas, Amsterdam.\"},{\"name\":\"Orgs\",\"dur\":6,\"desc\":\"Camera pulls back while neon beams trace out to all 11 organizations, each popping in.\"},{\"name\":\"Products\",\"dur\":5,\"desc\":\"Camera moves to the flagship arc; product domains appear on Zakana, Alienway, Pushasaco, kugguk.\"},{\"name\":\"Experiments\",\"dur\":4,\"desc\":\"Camera pans to EncapsulatorP; math experiment repos spawn as nodes.\"},{\"name\":\"Index\",\"dur\":4,\"desc\":\"Full pull-back reveals the whole constellation and the complete public + private index panel.\"}]';<\u002Fscript>\nwindow.OM_PLAYBACK = '{\"mode\":\"loop\"}';<\u002Fscript>\nwindow.TWEAK_DEFAULTS = /*EDITMODE-BEGIN*/{\n  \"motionEditor\": true,\n  \"accent\": \"#ffb457\",\n  \"scanlines\": true,\n  \"glitch\": 0.6\n}/*EDITMODE-END*/;<\u002Fscript>\n<\u002Fx-import>\n<\u002Fx-dc>\n\n\n<\u002Fbody><\u002Fhtml>"
